-- DA-DA MM2 MINI
-- Compact standalone version
-- No external branding references.

local P=game:GetService("Players")
local RS=game:GetService("RunService")
local UIS=game:GetService("UserInputService")
local L=game:GetService("Lighting")
local TS=game:GetService("TeleportService")
local LP=P.LocalPlayer
local Cam=workspace.CurrentCamera
local CG=game:GetService("CoreGui")

local S={
 ESP=false,RoleESP=true,Aim=false,FOV=180,Speed=16,Jump=50,
 Noclip=false,Fly=false,FlySpeed=60,FullBright=false,NoFog=false,
 AntiAFK=true,AutoGrabGun=false,GunTracer=false,Target=nil,oldFog=L.FogEnd,oldBright=L.Brightness,
 oldTime=L.ClockTime,oldFogStart=L.FogStart,oldFogColor=L.FogColor,esp={},worldESP={},trapESP={},muteReload=false}
}

local function char(p)return p and p.Character end
local function root(p)local c=char(p);return c and c:FindFirstChild("HumanoidRootPart")end
local function hum(p)local c=char(p);return c and c:FindFirstChildOfClass("Humanoid")end
local function alive(p)local h=hum(p);return h and h.Health>0 end
local function note(t,x)pcall(function()game:GetService("StarterGui"):SetCore("SendNotification",{Title=t,Text=x,Duration=2})end)end

local function role(p)
 local ok,d=pcall(function()
  local r=game:GetService("ReplicatedStorage"):FindFirstChild("GetPlayerData",true)
  return r and r:IsA("RemoteFunction") and r:InvokeServer()
 end)
 if ok and type(d)=="table" and d[p.Name] and d[p.Name].Role then return d[p.Name].Role end
 local c,b=char(p),p:FindFirstChildOfClass("Backpack")
 local function has(x,n)return x and x:FindFirstChild(n)~=nil end
 if has(c,"Knife")or has(b,"Knife")then return"Murderer"end
 if has(c,"Gun")or has(b,"Gun")then return"Sheriff"end
 return"Innocent"
end

local function nearest(filter)
 local a=root(LP);if not a then return end
 local best,dist
 for _,p in ipairs(P:GetPlayers())do
  if p~=LP and alive(p)and(not filter or filter(p))then
   local r=root(p)
   if r then local d=(r.Position-a.Position).Magnitude;if not dist or d<dist then best,dist=p,d end end
  end
 end
 return best,dist
end

local function murder()return nearest(function(p)return role(p)=="Murderer"end)end
local function sheriff()return nearest(function(p)return role(p)=="Sheriff"end)end

local function rm(p)
 local x=S.esp[p]
 if x then pcall(function()x:Destroy()end)S.esp[p]=nil end
end

local function esp(p)
 if p==LP or not S.ESP then return end
 rm(p);local r=root(p);if not r then return end
 local g=Instance.new("BillboardGui")
 g.Name="DADA_ESP";g.Adornee=r;g.Size=UDim2.fromOffset(150,30)
 g.StudsOffset=Vector3.new(0,3,0);g.AlwaysOnTop=true;g.Parent=r
 local t=Instance.new("TextLabel",g);t.BackgroundTransparency=1;t.Size=UDim2.fromScale(1,1)
 t.Font=Enum.Font.GothamBold;t.TextScaled=true;t.TextStrokeTransparency=.25
 t.Text=p.DisplayName.." ["..role(p).."]"
 local z=role(p)
 t.TextColor3=z=="Murderer" and Color3.fromRGB(255,70,70)
  or z=="Sheriff" and Color3.fromRGB(70,150,255)
  or Color3.new(1,1,1)
 S.esp[p]=g
end

local function refresh()
 for _,p in ipairs(P:GetPlayers())do
  if p~=LP then if S.ESP then esp(p)else rm(p)end end
 end
end

local function aimTarget()
 local best,bd= nil,S.FOV
 local c=Cam.ViewportSize/2
 for _,p in ipairs(P:GetPlayers())do
  if p~=LP and alive(p)then
   local r=root(p)
   if r then
    local q,v=Cam:WorldToViewportPoint(r.Position)
    if v and q.Z>0 then
     local d=(Vector2.new(q.X,q.Y)-c).Magnitude
     if d<bd then best,bd=p,d end
    end
   end
  end
 end
 return best
end

local function move()
 local h=hum(LP)
 if h then h.WalkSpeed=S.Speed;h.UseJumpPower=true;h.JumpPower=S.Jump end
end

local bv,bg
local function fly(on)
 S.Fly=on
 if bv then bv:Destroy();bv=nil end;if bg then bg:Destroy();bg=nil end
 if not on then return end
 local r=root(LP);if not r then return end
 bv=Instance.new("BodyVelocity",r);bv.MaxForce=Vector3.new(1e6,1e6,1e6)
 bg=Instance.new("BodyGyro",r);bg.MaxTorque=Vector3.new(1e6,1e6,1e6);bg.P=9000
end

local function tp(p)
 local a,b=root(LP),root(p)
 if a and b then a.CFrame=b.CFrame+Vector3.new(0,3,0)end
end

local function fling(p)
 local a,b=root(LP),root(p);if not a or not b then return end
 local old=a.CFrame
 for i=1,6 do
  a.CFrame=b.CFrame*CFrame.new(math.random(-2,2),0,math.random(-2,2))
  a.AssemblyLinearVelocity=Vector3.new(0,250,0);RS.Heartbeat:Wait()
 end
 a.CFrame=old;a.AssemblyLinearVelocity=Vector3.zero
end

-- Gun logic: dropped-gun pickup + shot tracer
local function hasKnife()
 local c=char(LP);local b=LP:FindFirstChildOfClass("Backpack")
 return (c and c:FindFirstChild("Knife")) or (b and b:FindFirstChild("Knife"))
end

local function roundAlive()
 local ok,m=pcall(function()
  return require(game:GetService("ReplicatedStorage"):WaitForChild("Modules"):WaitForChild("CurrentRoundClient"))
 end)
 if not ok or type(m)~="table" then return false end
 local d=m.PlayerData and m.PlayerData[LP.Name]
 return d and d.Role and not d.Dead
end

local function grabGun(obj)
 if not S.AutoGrabGun or hasKnife() or not roundAlive() then return end
 local r=root(LP);if not r then return end
 pcall(function()obj.CFrame=r.CFrame end)
 local pr=obj:FindFirstChildOfClass("ProximityPrompt")
 if pr and type(fireproximityprompt)=="function" then pcall(function()fireproximityprompt(pr)end)end
end

local function scanGuns()
 for _,o in ipairs(workspace:GetDescendants())do
  if o.Name=="GunDrop" and o:IsA("BasePart")then grabGun(o)end
 end
end

local gunConn
local function setAutoGrab(v)
 S.AutoGrabGun=v
 if gunConn then gunConn:Disconnect();gunConn=nil end
 if v then
  scanGuns()
  gunConn=workspace.DescendantAdded:Connect(function(o)
   if o.Name=="GunDrop" and o:IsA("BasePart")then task.wait(.1);grabGun(o)end
  end)
 end
end

local gunFireConn
local function setGunTracer(v)
 S.GunTracer=v
 if gunFireConn then gunFireConn:Disconnect();gunFireConn=nil end
 if not v then return end
 local ws=game:GetService("ReplicatedStorage"):FindFirstChild("ClientServices")
 ws=ws and ws:FindFirstChild("WeaponService")
 local fired=ws and ws:FindFirstChild("GunFired")
 if fired and fired:IsA("RemoteEvent")then
  gunFireConn=fired.OnClientEvent:Connect(function(gun,a,b)
   if not S.GunTracer then return end
   local c=char(LP);if not c then return end
   if typeof(gun)=="Instance" and not gun:IsDescendantOf(c)then return end
   local function pos(x)
    if typeof(x)=="Vector3"then return x end
    if typeof(x)=="CFrame"then return x.Position end
    if typeof(x)=="Instance"then
     if x:IsA("Attachment")then return x.WorldPosition end
     if x:IsA("BasePart")then return x.Position end
    end
   end
   local a1,b1=pos(a),pos(b);if not a1 or not b1 then return end
   local p1=Instance.new("Part");p1.Anchored=true;p1.CanCollide=false;p1.CanQuery=false
   p1.Transparency=1;p1.Size=Vector3.one;p1.Position=a1;p1.Parent=workspace
   local p2=p1:Clone();p2.Position=b1;p2.Parent=workspace
   local x=Instance.new("Attachment",p1);local y=Instance.new("Attachment",p2)
   local beam=Instance.new("Beam",p1);beam.Attachment0=x;beam.Attachment1=y
   beam.FaceCamera=true;beam.Width0=.16;beam.Width1=.16;beam.LightEmission=2
   beam.Color=ColorSequence.new(Color3.fromRGB(155,80,255))
   game:GetService("Debris"):AddItem(p1,1);game:GetService("Debris"):AddItem(p2,1)
  end)
 end
end

local function bright(v)
 S.FullBright=v
 if v then L.Brightness=3;L.ClockTime=14;L.FogEnd=1e6
 else L.Brightness=S.oldBright;L.ClockTime=S.oldTime;L.FogEnd=S.oldFog end
end

local function button(par,txt,fn)
 local b=Instance.new("TextButton",par);b.Size=UDim2.new(1,-8,0,42)
 b.BackgroundColor3=Color3.fromRGB(28,24,35);b.Text=txt;b.TextColor3=Color3.new(1,1,1)
 b.Font=Enum.Font.GothamBold;b.TextSize=13;Instance.new("UICorner",b).CornerRadius=UDim.new(0,10)
 b.MouseButton1Click:Connect(fn);return b
end

local function toggle(par,txt,get,set)
 local b=button(par,txt,function()set(not get())end)
 local function paint()b.BackgroundColor3=get() and Color3.fromRGB(105,48,140)or Color3.fromRGB(28,24,35)end
 local old=set;return b
end

local old=CG:FindFirstChild("DADA_MINI");if old then old:Destroy()end
local G=Instance.new("ScreenGui",CG);G.Name="DADA_MINI";G.ResetOnSpawn=false

local O=Instance.new("TextButton",G);O.Size=UDim2.fromOffset(58,58);O.Position=UDim2.new(0,16,.5,-29)
O.BackgroundColor3=Color3.fromRGB(25,20,34);O.Text="D";O.TextColor3=Color3.new(1,1,1)
O.Font=Enum.Font.GothamBlack;O.TextSize=28;Instance.new("UICorner",O).CornerRadius=UDim.new(1,0)

