RS.Stepped:Connect(function()
 if S.Noclip then local c=char(LP);if c then for _,v in ipairs(c:GetDescendants())do if v:IsA("BasePart")then v.CanCollide=false end end end end
 move()
 if S.Aim then local p=aimTarget();local r=p and root(p);if r then Cam.CFrame=CFrame.lookAt(Cam.CFrame.Position,r.Position)end end
 if S.Fly and bv and bg then
  local d=Vector3.zero
  if UIS:IsKeyDown(Enum.KeyCode.W)then d+=Cam.CFrame.LookVector end
  if UIS:IsKeyDown(Enum.KeyCode.S)then d-=Cam.CFrame.LookVector end
  if UIS:IsKeyDown(Enum.KeyCode.A)then d-=Cam.CFrame.RightVector end
  if UIS:IsKeyDown(Enum.KeyCode.D)then d+=Cam.CFrame.RightVector end
  if UIS:IsKeyDown(Enum.KeyCode.Space)then d+=Vector3.yAxis end
  if UIS:IsKeyDown(Enum.KeyCode.LeftControl)then d-=Vector3.yAxis end
  bv.Velocity=d.Magnitude>0 and d.Unit*S.FlySpeed or Vector3.zero;bg.CFrame=Cam.CFrame
 end
end)

pcall(function()
 local V=game:GetService("VirtualUser")
 LP.Idled:Connect(function()if S.AntiAFK then V:Button2Down(Vector2.zero,Cam.CFrame);task.wait(.1);V:Button2Up(Vector2.zero,Cam.CFrame)end end)
end)


-- ============================================================
-- DA-DA EXTRA PACK
-- ============================================================
do
    local function dadaNotify(msg)
        pcall(function() note("DA-DA", tostring(msg)) end)
    end

    -- Character state snapshot / restore helpers.
    local function dadaCharacter()
        return LP.Character or LP.CharacterAdded:Wait()
    end

    local function dadaRoot()
        local c=dadaCharacter()
        return c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("UpperTorso") or c:FindFirstChild("Torso")
    end

    local function dadaNearestPlayer(maxDist)
        local root=dadaRoot(); if not root then return nil end
        local best,bestD=nil,maxDist or math.huge
        for _,plr in ipairs(Players:GetPlayers()) do
            if plr~=LP and plr.Character then
                local r=plr.Character:FindFirstChild("HumanoidRootPart")
                local h=plr.Character:FindFirstChildOfClass("Humanoid")
                if r and h and h.Health>0 then
                    local d=(r.Position-root.Position).Magnitude
                    if d<bestD then best,bestD=plr,d end
                end
            end
        end
        return best
    end

    local function dadaRefresh()
        pcall(function()
            if S.GunESP then setGunESP(false); setGunESP(true) end
            if S.TrapESP then setTrapESP(false); setTrapESP(true) end
        end)
        dadaNotify("Refresh complete")
    end

    local function dadaClearEffects()
        pcall(function()
            clearWorldESP()
            if S.GunESP then S.GunESP=false end
            if S.TrapESP then S.TrapESP=false end
        end)
        dadaNotify("World ESP cleared")
    end

    local function dadaRoundInfo()
        pcall(function()
            local r=get_round and get_round()
            if r then dadaNotify("Round detected") else dadaNotify("Round not detected") end
        end)
    end

    -- Small utility buttons. They do not replace the existing UI.
    button(SFrame,"Refresh ESP",dadaRefresh)
    button(SFrame,"Clear ESP",dadaClearEffects)
    button(SFrame,"Round Check",dadaRoundInfo)
end

-- ============================================================
-- DA-DA KITI EXTRA PACK
-- Adapted features that were not already present in the mini build.
-- ============================================================

do
 local K=getgenv().DADA_KITI_EXTRA or {}
 getgenv().DADA_KITI_EXTRA=K
 K.conns=K.conns or {}
 K.fx=K.fx or {}
 K.enabled=K.enabled or {}

 local function disconnect(name)
  local c=K.conns[name]
  if c then pcall(function() c:Disconnect() end);K.conns[name]=nil end
 end
 local function setconn(name,c)
  disconnect(name);K.conns[name]=c
 end
 local function destroy(name)
  local x=K.fx[name]
  if x then pcall(function() x:Destroy() end);K.fx[name]=nil end
 end
 local function rootPart(p)return p and p.Character and p.Character:FindFirstChild("HumanoidRootPart")end
 local function mkPart(pos)
  local x=Instance.new("Part")
  x.Anchored=true;x.CanCollide=false;x.CanQuery=false;x.CanTouch=false;x.Transparency=1
  x.Size=Vector3.one;x.Position=pos;x.Parent=workspace
  return x
 end

 -- Crosshair
 local function crosshair(on)
  K.enabled.Crosshair=on
  if not on then destroy("Crosshair");return end
  local old=G:FindFirstChild("DADA_CROSSHAIR")
  if old then old:Destroy() end
  local sg=Instance.new("ScreenGui",G);sg.Name="DADA_CROSSHAIR";sg.IgnoreGuiInset=true
  local holder=Instance.new("Frame",sg);holder.BackgroundTransparency=1
  holder.Size=UDim2.fromOffset(40,40);holder.Position=UDim2.new(.5,-20,.5,-20)
  local function line(x,y,w,h)
   local f=Instance.new("Frame",holder);f.BorderSizePixel=0;f.BackgroundColor3=Color3.fromRGB(255,255,255)
   f.Size=UDim2.fromOffset(w,h);f.Position=UDim2.fromOffset(x,y);return f
  end
  line(19,2,2,12);line(19,26,2,12);line(2,19,12,2);line(26,19,12,2)
  K.fx.Crosshair=sg
 end

 -- Target HUD
 local function targetHUD(on)
  K.enabled.TargetHUD=on
  destroy("TargetHUD")
  if not on then return end
  local sg=Instance.new("ScreenGui",G);sg.Name="DADA_TARGET_HUD";sg.ResetOnSpawn=false
  local f=Instance.new("Frame",sg);f.Size=UDim2.fromOffset(210,54);f.Position=UDim2.new(.5,-105,0,16)
  f.BackgroundColor3=Color3.fromRGB(18,15,24);f.BorderSizePixel=0;Instance.new("UICorner",f).CornerRadius=UDim.new(0,10)
  local t=Instance.new("TextLabel",f);t.BackgroundTransparency=1;t.Size=UDim2.fromScale(1,1);t.Font=Enum.Font.GothamBold;t.TextSize=14;t.TextColor3=Color3.new(1,1,1)
  K.fx.TargetHUD=sg
  setconn("TargetHUD",RS.RenderStepped:Connect(function()
   local p=S.Target
   if p and p.Parent and alive(p) then t.Text=p.DisplayName.."  •  "..role(p) else t.Text="No target" end
  end))
 end

 -- Custom FOV
 local fovOriginal=Cam and Cam.FieldOfView or 70
 local function customFOV(on,value)
  K.enabled.FOV=on;K.FOV=value or K.FOV or 90
  if on then
   if Cam then Cam.FieldOfView=K.FOV end
   setconn("FOV",RS.RenderStepped:Connect(function()
    if K.enabled.FOV and workspace.CurrentCamera then workspace.CurrentCamera.FieldOfView=K.FOV end
   end))
  else
   disconnect("FOV")
   if workspace.CurrentCamera then workspace.CurrentCamera.FieldOfView=fovOriginal end
  end
 end

 -- Hit particles / hit sound: watches health changes on other players.
 local function clearHitWatch()
  for n in pairs(K.conns) do if n:sub(1,5)=="Hit_" then disconnect(n) end end
 end
 local function hitFX(p)
  local r=rootPart(p);if not r then return end
  if K.enabled.HitParticles then
   local a=Instance.new("Attachment",r)
   local pe=Instance.new("ParticleEmitter",a);pe.Rate=0;pe.Lifetime=NumberRange.new(.25,.5);pe.Speed=NumberRange.new(4,8)
   pe.SpreadAngle=Vector2.new(180,180);pe.Texture="rbxassetid://243098098";pe.Color=ColorSequence.new(Color3.fromRGB(255,70,70));pe:Emit(18)
   game:GetService("Debris"):AddItem(a,1)
  end
  if K.enabled.HitSound then
   local snd=Instance.new("Sound",r);snd.SoundId="rbxassetid://12222216";snd.Volume=.65;snd:Play();game:GetService("Debris"):AddItem(snd,2)
  end
 end
 local function watchHits(on)
  K.enabled.HitWatch=on;clearHitWatch()
  if not on then return end
  for _,p in ipairs(P:GetPlayers()) do
   if p~=LP then
    local h=hum(p)
    if h then
     local last=h.Health
     setconn("Hit_"..p.UserId,h.HealthChanged:Connect(function(v)
      if v<last and last>0 then hitFX(p) end
      last=v
     end))
    end
   end
  end
 end

 -- Murder death effect
 local function murderEffect(on)
  K.enabled.MurderEffect=on
  disconnect("MurderEffect")
  if not on then return end
  setconn("MurderEffect",P.PlayerAdded:Connect(function() end))
  local function scan()
   local m=murder();if not m then return end
   local h=hum(m);if not h or K.murderHum==h then return end
   K.murderHum=h
   setconn("MurderDeath",h.Died:Connect(function()
    local r=rootPart(m);if not r then return end
    local a=Instance.new("Attachment",r);local pe=Instance.new("ParticleEmitter",a)
    pe.Rate=0;pe.Lifetime=NumberRange.new(.4,.8);pe.Speed=NumberRange.new(8,14);pe.SpreadAngle=Vector2.new(180,180)
    pe.Color=ColorSequence.new(Color3.fromRGB(255,40,40));pe:Emit(45);game:GetService("Debris"):AddItem(a,2)
    note("DA-DA","Murderer eliminated")
   end))
  end
  setconn("MurderScan",RS.Heartbeat:Connect(function() if K.enabled.MurderEffect then pcall(scan) end end))
 end

 -- Self chams / tool chams
 local function selfChams(on)
  K.enabled.SelfChams=on
  destroy("SelfChams")
  if not on then return end
  local c=char(LP);if not c then return end
  local h=Instance.new("Highlight",c);h.Name="DADA_SELF_CHAMS";h.FillColor=Color3.fromRGB(155,70,255);h.OutlineColor=Color3.fromRGB(255,255,255);h.FillTransparency=.45;h.OutlineTransparency=.05
  K.fx.SelfChams=h
 end
 local function toolChams(on)
  K.enabled.ToolChams=on
  if not on then
   for _,v in ipairs(c or {}) do end
   for _,o in ipairs(workspace:GetDescendants()) do if o.Name=="DADA_TOOL_CHAM" then pcall(function()o:Destroy()end) end end
   return
  end
  local function apply()
   local c=char(LP);if not c then return end
   for _,o in ipairs(c:GetChildren()) do
    if o:IsA("Tool") then
     local h=o:FindFirstChild("DADA_TOOL_CHAM")
     if not h then h=Instance.new("Highlight",o);h.Name="DADA_TOOL_CHAM";h.FillColor=Color3.fromRGB(255,80,80);h.OutlineColor=Color3.new(1,1,1);h.FillTransparency=.4 end
    end
   end
  end
  apply();setconn("ToolChams",RS.Heartbeat:Connect(apply))
 end

 -- World sky presets
 local function clearSky()
  for _,o in ipairs(L:GetChildren()) do if o:IsA("Sky") and o.Name=="DADA_SKY" then o:Destroy() end end
 end
 local skies={
  Purple={"rbxassetid://159454299","rbxassetid://159454299","rbxassetid://159454299","rbxassetid://159454299","rbxassetid://159454299","rbxassetid://159454299"},
  RedNight={"rbxassetid://401664839","rbxassetid://401664839","rbxassetid://401664839","rbxassetid://401664839","rbxassetid://401664839","rbxassetid://401664839"}
 }
 local function skyPreset(name)
  clearSky();local ids=skies[name] or skies.Purple;local s=Instance.new("Sky",L);s.Name="DADA_SKY"
  s.SkyboxBk=ids[1];s.SkyboxDn=ids[2];s.SkyboxFt=ids[3];s.SkyboxLf=ids[4];s.SkyboxRt=ids[5];s.SkyboxUp=ids[6]
 end

 -- Custom fog
 local fogOld={L.FogStart,L.FogEnd,L.FogColor}
 local function customFog(on)
  K.enabled.CustomFog=on
  if on then L.FogStart=0;L.FogEnd=120;L.FogColor=Color3.fromRGB(115,80,140)
  else L.FogStart=fogOld[1];L.FogEnd=fogOld[2];L.FogColor=fogOld[3] end
 end

 -- Infinite jump / bhop / auto strafe
 local function infiniteJump(on)
  K.enabled.InfiniteJump=on;disconnect("InfiniteJump")
  if not on then return end
  setconn("InfiniteJump",UIS.JumpRequest:Connect(function()
   local h=hum(LP);if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end
  end))
 end
 local function bhop(on)
  K.enabled.Bhop=on;disconnect("Bhop")
  if not on then return end
  setconn("Bhop",RS.Heartbeat:Connect(function()
   local h=hum(LP);if h and h.FloorMaterial~=Enum.Material.Air then h.Jump=true end
  end))
 end
 local function autoStrafe(on)
  K.enabled.AutoStrafe=on;disconnect("AutoStrafe")
  if not on then return end
  setconn("AutoStrafe",RS.RenderStepped:Connect(function()
   local r=root(LP);local h=hum(LP);if r and h and h.MoveDirection.Magnitude>0 then
    local v=r.AssemblyLinearVelocity;r.AssemblyLinearVelocity=Vector3.new(h.MoveDirection.X*math.max(v.Magnitude,16),v.Y,h.MoveDirection.Z*math.max(v.Magnitude,16))
   end
  end))
 end

 -- Auto reset if murderer is detected near the local player.
 local function autoReset(on)
  K.enabled.AutoReset=on;disconnect("AutoReset")
  if not on then return end
  setconn("AutoReset",RS.Heartbeat:Connect(function()
   local m=murder();local a=root(LP);local b=root(m)
   if m and a and b and (a.Position-b.Position).Magnitude<8 then
    local h=hum(LP);if h then h.Health=0 end
   end
  end))
 end

 -- Role notifications
 local function roleNotify(on)
  K.enabled.RoleNotify=on;disconnect("RoleNotify");K.lastRole=nil
  if not on then return end
  setconn("RoleNotify",task.spawn(function()
   while K.enabled.RoleNotify do
    local r=role(LP)
    if r and r~=K.lastRole then K.lastRole=r;note("DA-DA", "Role: "..r) end
    task.wait(.6)
   end
  end))
 end

 -- Anti-trap and local coin cleanup
 local function antiTrap(on)
  K.enabled.AntiTrap=on;disconnect("AntiTrap")
  if not on then return end
  setconn("AntiTrap",workspace.DescendantAdded:Connect(function(o)
   if o:IsA("BasePart") then local n=string.lower(o.Name);if n:find("trap",1,true) or n:find("spike",1,true) then pcall(function()o.CanTouch=false;o.CanCollide=false;o.Transparency=1 end) end end
  end))
  for _,o in ipairs(workspace:GetDescendants()) do if o:IsA("BasePart") then local n=string.lower(o.Name);if n:find("trap",1,true) or n:find("spike",1,true) then pcall(function()o.CanTouch=false;o.CanCollide=false;o.Transparency=1 end) end end end
 end
 local function clearCoins()
  for _,o in ipairs(workspace:GetDescendants()) do
   local n=string.lower(o.Name);if n:find("coin",1,true) then pcall(function()o.LocalTransparencyModifier=1 end) end
  end
 end

 -- Random/lobby teleport helpers
 local function tpRandom()
  local spots={}
  for _,o in ipairs(workspace:GetDescendants()) do
   if o:IsA("SpawnLocation") then table.insert(spots,o) end
  end
  local a=root(LP);local x=spots[math.random(1,math.max(1,#spots))]
  if a and x then a.CFrame=x.CFrame+Vector3.new(0,3,0) end
 end
 local function tpLobby()
  local a=root(LP);if not a then return end
  for _,o in ipairs(workspace:GetDescendants()) do
   if o:IsA("SpawnLocation") and string.find(string.lower(o.Name),"lobby",1,true) then a.CFrame=o.CFrame+Vector3.new(0,3,0);return end
  end
  note("DA-DA","Lobby spawn not found")
 end

 -- Buttons: only features not already present in the mini build.
 button(SFrame,"Crosshair",function()crosshair(not K.enabled.Crosshair)end)
 button(SFrame,"Target HUD",function()targetHUD(not K.enabled.TargetHUD)end)
 button(SFrame,"Custom FOV",function()customFOV(not K.enabled.FOV,90)end)
 button(SFrame,"Hit Particles",function()watchHits(not K.enabled.HitParticles);K.enabled.HitParticles=not K.enabled.HitParticles;watchHits(K.enabled.HitParticles or K.enabled.HitSound)end)
 button(SFrame,"Hit Sound",function()K.enabled.HitSound=not K.enabled.HitSound;watchHits(K.enabled.HitParticles or K.enabled.HitSound)end)
 button(SFrame,"Murder Effect",function()murderEffect(not K.enabled.MurderEffect)end)
 button(SFrame,"Self Chams",function()selfChams(not K.enabled.SelfChams)end)
 button(SFrame,"Tool Chams",function()toolChams(not K.enabled.ToolChams)end)
 button(SFrame,"Purple Sky",function()skyPreset("Purple")end)
 button(SFrame,"Red Night Sky",function()skyPreset("RedNight")end)
 button(SFrame,"Clear Custom Sky",clearSky)
 button(SFrame,"Custom Fog",function()customFog(not K.enabled.CustomFog)end)
 button(SFrame,"Infinite Jump",function()infiniteJump(not K.enabled.InfiniteJump)end)
 button(SFrame,"Bhop",function()bhop(not K.enabled.Bhop)end)
 button(SFrame,"Auto Strafe",function()autoStrafe(not K.enabled.AutoStrafe)end)
 button(SFrame,"Auto Reset Near Murderer",function()autoReset(not K.enabled.AutoReset)end)
 button(SFrame,"Role Notifications",function()roleNotify(not K.enabled.RoleNotify)end)
 button(SFrame,"Anti Trap",function()antiTrap(not K.enabled.AntiTrap)end)
 button(SFrame,"Clear Coins",clearCoins)
 button(SFrame,"Teleport Random Spawn",tpRandom)
 button(SFrame,"Teleport Lobby",tpLobby)

 LP.CharacterAdded:Connect(function()
  task.wait(.5)
  if K.enabled.SelfChams then selfChams(true) end
 end)
end

